def signal(obs):
    # simple momentum: past 30, threshold 5 for A, 5 for others scaled
    # target = sign(past_ret) if |past_ret| > thresh else 0
    targets = {}
    params = {'A':(30,5),'B':(100,8),'C':(50,4),'IDX':(30,5)}
    for asset in obs.assets:
        p, thr = params.get(asset, (30,5))
        mids = obs.hist(asset,'mid',p+1)
        # mids may contain NaN
        if mids is None or len(mids) < p+1 or np.isnan(mids[0]) or np.isnan(mids[-1]):
            continue
        past_ret = mids[-1] - mids[0]
        if abs(past_ret) > thr:
            targets[asset] = 1.0 if past_ret>0 else -1.0
        else:
            targets[asset] = 0.0
    return targets

def signal(obs):
    targets = {}
    # helper to safely get past return
    def get_past(asset, p):
        h = obs.hist(asset, 'mid', p+1)
        if h is None or len(h) < p+1:
            return None
        a = h[0]
        b = h[-1]
        if a is None or b is None:
            return None
        # np NaN check without import
        if a != a or b != b:
            return None
        return b - a

    # A: 30-step momentum + imbalance boost
    pr = get_past('A', 30)
    if pr is not None:
        imb = obs.last('A', 'imbalance')
        if imb is not None and imb == imb:
            pr = pr + 7.0 * imb
        if abs(pr) > 8.0:
            targets['A'] = 1.0 if pr > 0 else -1.0
        else:
            targets['A'] = 0.0
    # C: 50-step momentum
    pr = get_past('C', 50)
    if pr is not None:
        if abs(pr) > 6.0:
            targets['C'] = 1.0 if pr > 0 else -1.0
        else:
            targets['C'] = 0.0
    # IDX: 30-step momentum
    pr = get_past('IDX', 30)
    if pr is not None:
        if abs(pr) > 6.0:
            targets['IDX'] = 1.0 if pr > 0 else -1.0
        else:
            targets['IDX'] = 0.0
    # B: long-horizon weak momentum, smaller size and higher threshold to avoid whipsaw
    pr = get_past('B', 100)
    if pr is not None:
        if abs(pr) > 12.0:
            targets['B'] = 0.5 if pr > 0 else -0.5
        else:
            targets['B'] = 0.0
    return targets

