def signal(obs):
    # Slow momentum with hysteresis to cut turnover
    # state holds previous raw signal for smoothing
    s = obs.state
    if 'prev' not in s:
        s['prev'] = {}
        s['hold'] = {}
    targets = {}
    # Use longer lookbacks, trade only when conviction high
    for asset in obs.assets:
        try:
            # need 220 steps
            mids = obs.hist(asset, 'mid', 220)
            if mids is None or len(mids) < 210:
                continue
            if np.isnan(mids[-1]) or np.isnan(mids[-101]) or np.isnan(mids[-201]):
                continue
            # 100 and 200 step momentum
            mom100 = mids[-1] - mids[-101]
            mom50 = mids[-1] - mids[-51]
            # volatility estimate over last 100 diffs
            diffs = mids[1:] - mids[:-1]
            valid = ~np.isnan(diffs)
            if np.sum(valid) < 80:
                continue
            vol = np.nanstd(diffs[valid][-100:])
            if vol < 0.4 or np.isnan(vol):
                continue
            # normalized scores
            z100 = mom100 / (vol * 10.0)   # sqrt(100)=10
            z50 = mom50 / (vol * 7.0710678118654755)
            z = 0.7 * z100 + 0.3 * z50
            # strong threshold - only act if |z| > 0.6 to avoid whipsaw
            # hysteresis: keep previous direction unless opposite signal strong
            prev = s['prev'].get(asset, 0.0)
            hold = s['hold'].get(asset, 0)
            # decay hold counter
            if hold > 0:
                s['hold'][asset] = hold - 1
                # keep previous target while holding
                if asset in s['prev']:
                    # don't update, keep previous target value
                    # we still need to return previous target to avoid engine rebalancing
                    # find last target we emitted: store in state
                    pass
            # compute raw desired position
            raw = np.tanh(z * 0.65)  # 0.65 scaling
            # apply dead band and hysteresis
            # if we are currently long (prev>0.2) need strong negative to flip
            # flip thresholds: 0.5 for continuation, -0.2 for flip? Let's implement
            if prev > 0.25:
                # need z < -0.4 to flip, otherwise stay
                if z < -0.45:
                    desired = raw
                else:
                    # keep positive, but allow gradual decay towards raw if raw positive
                    if raw > 0.25:
                        desired = 0.6*prev + 0.4*raw
                    else:
                        desired = prev * 0.98  # slow decay
            elif prev < -0.25:
                if z > 0.45:
                    desired = raw
                else:
                    if raw < -0.25:
                        desired = 0.6*prev + 0.4*raw
                    else:
                        desired = prev * 0.98
            else:
                # neutral, need strong signal to enter
                if abs(z) < 0.55:
                    desired = prev * 0.9  # stay neutral
                else:
                    desired = raw * 0.7  # enter partially

            # clip
            if desired > 1: desired = 1
            if desired < -1: desired = -1
            # small change filter: if change <0.08 don't trade (keep old target by not returning?)
            # To avoid turnover, we return same as previous if change small
            # But we must return something to keep target; we will keep prev if change small
            if abs(desired - prev) < 0.12:
                desired = prev
                # increase hold to avoid jitter
                s['hold'][asset] = 2
            # store
            s['prev'][asset] = float(desired)
            # only emit if meaningful size
            if abs(desired) < 0.15:
                # return 0 to flatten slowly but we still count as target 0 -> may cause trade to flatten, but that's needed
                # Instead, if we are already near 0, keep 0
                if abs(prev) < 0.15:
                    desired = 0.0
                    s['prev'][asset] = 0.0
                # else we keep decaying as above
            targets[asset] = float(desired)
        except:
            continue
    # Only trade assets with strong edge: A and IDX primary, B/C reduced
    # Scale down B/C to 0.5 because their short-term edge is weaker after costs
    for a in ['B','C']:
        if a in targets:
            targets[a] = float(targets[a] * 0.45)
    return targets

