    past = mid[horizon_past: -horizon_fwd] - mid[:-horizon_past-horizon_fwd] if horizon_fwd>0 else mid[horizon_past:]-mid[:-horizon_past]
    fwd = mid[horizon_past+horizon_fwd:]-mid[horizon_past:-horizon_fwd] if horizon_fwd>0 else np.diff(mid[horizon_past:])
