def signal(obs):
    # adaptive z-score arb on IDX vs basket
    # rolling 500 window, z threshold 1.5
    a = obs.last('A','mid'); b=obs.last('B','mid'); c=obs.last('C','mid'); idx=obs.last('IDX','mid')
    if a is None or b is None or c is None or idx is None: return {}
    if a!=a or b!=b or c!=c or idx!=idx: return {}
    fair = 0.3333*a + 0.6667*b + 0.1667*c
    diff = fair - idx
    hist_len = 500
    # maintain deque of diff history in state
    buf = obs.state.get('buf')
    if buf is None:
        buf=[]
    buf.append(float(diff))
    if len(buf) > hist_len+20:
        buf = buf[-hist_len-20:]
    obs.state['buf']=buf
    if len(buf) < hist_len+10:
        return {}
    # compute rolling mean/std over last hist_len diffs excluding recent 10? Use trailing
    window = buf[-hist_len:]
    # exclude NaN already not present
    m = sum(window)/len(window)
    # std
    v = sum((x-m)*(x-m) for x in window)/len(window)
    s = (v**0.5) if v>0 else 1.0
    if s < 1e-6:
        s=1.0
    z = (diff - m)/s
    # hysteresis: enter at 1.5, exit at 0.8
    prev = obs.state.get('p',0.0)
    # z positive means fair > idx => IDX underpriced => long IDX (tgt +1)
    if z > 1.5:
        tgt=1.0
    elif z < -1.5:
        tgt=-1.0
    elif abs(z) < 0.6:
        tgt=0.0
    else:
        tgt=prev
    obs.state['p']=tgt
    return {'IDX': float(tgt)}

def signal(obs):
    a = obs.last('A','mid')
    b = obs.last('B','mid')
    c = obs.last('C','mid')
    idx = obs.last('IDX','mid')
    if a is None or b is None or c is None or idx is None:
        return {}
    # NaN check
    if a!=a or b!=b or c!=c or idx!=idx:
        return {}
    fair = 0.3333*a + 0.6667*b + 0.1667*c
    diff = fair - idx
    # state buffer of diffs (one per signal call ~10 steps)
    buf = obs.state.get('buf')
    if buf is None:
        buf = []
    buf.append(float(diff))
    # keep last 800
    if len(buf) > 800:
        buf = buf[-800:]
    obs.state['buf'] = buf
    # need enough history: 200 calls = 2000 steps ~ responsive to drift
    win = 200
    if len(buf) < win:
        return {}
    window = buf[-win:]
    m = sum(window)/win
    # variance
    var = 0.0
    for x in window:
        d = x - m
        var += d*d
    var /= win
    s = var**0.5 if var > 0 else 8.0
    # floor to avoid tiny std blow up, but keep adaptive
    if s < 4.0:
        s = 4.0
    if s > 12.0:
        s = 12.0
    z = (diff - m)/s if s != 0 else 0.0
    prev = obs.state.get('p', 0.0)
    # hysteresis: entry 1.1 sigma, exit 0.5 sigma
    if z > 1.1:
        tgt = 1.0
    elif z < -1.1:
        tgt = -1.0
    elif abs(z) < 0.5:
        tgt = 0.0
    else:
        tgt = prev
    obs.state['p'] = tgt
    if tgt == 0.0:
        return {'IDX': 0.0, 'A': 0.0, 'B': 0.0, 'C': 0.0}
    # hedged basket to be market neutral
    # IDX target = tgt, basket opposite with share weights
    # scale so IDX 1 = 10 lots, basket components proportional
    return {'IDX': float(tgt), 'A': float(-tgt*0.3333), 'B': float(-tgt*0.6667), 'C': float(-tgt*0.1667)}

