def corr(a,b):
    m=np.isfinite(a)&np.isfinite(b)
    if int(m.sum())<100:
        return 0.0
    aa=a[m]; bb=b[m]
    sa=np.std(aa); sb=np.std(bb)
    if sa==0 or sb==0:
        return 0.0
    return float(np.mean((aa-np.mean(aa))*(bb-np.mean(bb)))/(sa*sb))
