    if len(hist) > 80:
        hist = hist[-80:]
    obs.state['hist'] = hist
    if len(hist) < 30:
        return {}
    # rolling mean/std
    n = len(hist)
    m = sum(hist)/n
    var = 0.0
    for x in hist:
        d = x - m
        var += d*d
    std = (var/n) ** 0.5
    if std < 1e-9 or std != std:
        return {}
    # adaptive z using rolling stats (exclude current diff from mean? already included but ok)
    z = (diff - m) / std
    prev = obs.state.get('p', 0.0)
    # entry on large deviation, hold 100-200 steps for convergence, exit near zero
    if z > 2.0:
        tgt = 1.0
    elif z < -2.0:
        tgt = -1.0
    elif abs(z) < 0.5:
        tgt = 0.0
    else:
        tgt = prev
    obs.state['p'] = tgt
    return {'IDX': float(tgt)}

